sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    try {
        var mssCustodyOutboundRec = current.response_to.agent_correlator.toString();
        var response = "";
        var xmlDoc = new XMLDocument2();
        xmlDoc.parseXML(current.payload.toString());
        response = xmlDoc.getNodeText("//result/output");
        var httpCodeNode = xmlDoc.getNode("//parameters/parameter");
        var httpCode = httpCodeNode.getAttribute('value');

        var grMssCustodyOutbound = new GlideRecord("x_hsb11_mss_custod_mss_custody_unity_ondemand_staging");
        grMssCustodyOutbound.addEncodedQuery('state=Processsing^refresh_end_timeISEMPTY^trade_base='+ mssCustodyOutboundRec);
        grMssCustodyOutbound.query();
        if (grMssCustodyOutbound.next()) {
            grMssCustodyOutbound.response_date = new GlideDateTime();
            grMssCustodyOutbound.response_body = response;
            grMssCustodyOutbound.error_code = httpCode;
            grMssCustodyOutbound.error_body = response;
            var errorCodes = gs.getProperty('x_hsb11_mss_custod.mss_custody_onDemand_error_codes').toString().split(',');
            if (httpCode == '200') {
                grMssCustodyOutbound.state = "Processed";
				//Modified below logic a part of MSSOTIQUBE-1816 wherein not going to create records into staging table
                //new x_hsb11_mss_custod.MSSCustodyOnDemandCallUtils().updateTradeDataPostAPICall(mssCustodyOutboundRec, httpCode, response);
            } else if (errorCodes.indexOf(httpCode) != -1) {
                grMssCustodyOutbound.state = "Error";
                grMssCustodyOutbound.retry_count++;
            } else {
                grMssCustodyOutbound.state = "Error";
				var retryLimit = gs.getProperty("x_hsb11_mss_custod.mss_custody_outbound_retry_count");
                grMssCustodyOutbound.retry_count = retryLimit;
            }
            grMssCustodyOutbound.update();
        }
    } catch (e) {
        gs.info("MSSOTIQUBE-1816 - Exception from BR - MSS Custody HSBC SensorOnDemand Response" + e.message);
    }

})(current, previous);
